import json
from datetime import datetime
from collections import defaultdict
from difflib import SequenceMatcher

import csv
import os

DATA_DIR = '/app/dataset'


def load_data():
    emps_list = []
    with open(os.path.join(DATA_DIR, 'employees.csv')) as f:
        reader = csv.DictReader(f)
        for r in reader:
            emps_list.append(r)
    emps = {e['PESEL']: e for e in emps_list}

    tasks_list = []
    with open(os.path.join(DATA_DIR, 'tasks.csv')) as f:
        reader = csv.DictReader(f)
        for r in reader:
            tasks_list.append(r)
    tasks = {t['task_id']: t for t in tasks_list}

    return emps_list, emps, tasks


def correct_eid(eid, emps_list, emps):
    if eid in emps:
        return eid
    best = None
    best_score = -1
    for e in emps_list:
        pid = e['PESEL']
        score = SequenceMatcher(None, eid, pid).ratio()
        if score > best_score:
            best_score = score
            best = pid
    if best_score >= 0.7:
        return best
    return None


def parse_tasks(s):
    s = s.strip()
    if s == '[]':
        return []
    try:
        parsed = json.loads(s)
        return [str(x) for x in parsed]
    except:
        s2 = s.replace('[', '').replace(']', '')
        parts = []
        for x in s2.split(','):
            x = x.strip()
            if x:
                parts.append(x)
        return parts


def parse_date(s):
    try:
        return datetime.strptime(s, '%Y-%m-%d')
    except Exception:
        if s.endswith('-31'):
            # try common months with 30 days
            for m in ['-04-', '-06-', '-09-', '-11-']:
                if m in s:
                    try:
                        return datetime.strptime(s.replace('-31', '-30'), '%Y-%m-%d')
                    except Exception:
                        pass
            try:
                return datetime.strptime(s.replace('-31', '-28'), '%Y-%m-%d')
            except Exception:
                pass
        return None


def answer() -> dict[str, list[int]]:
    emps_list, emps, tasks = load_data()

    result = defaultdict(lambda: defaultdict(float))  # eid -> (year, month) -> total

    with open(os.path.join(DATA_DIR, 'timesheet.csv')) as f:
        reader = csv.DictReader(f)
        for r in reader:
            d = parse_date(r['date'])
            if not d:
                continue
            ce = correct_eid(r['employee_id'], emps_list, emps)
            if not ce:
                continue
            try:
                h = float(r['hours_worked'])
            except Exception:
                continue

            bonus = 0.0
            tlist = parse_tasks(r['performed_tasks'])
            for tid in tlist:
                if tid in tasks:
                    try:
                        bonus += float(tasks[tid]['pay_per_completion'])
                    except Exception:
                        pass

            rate = float(emps[ce]['hourly_rate'])
            total = h * rate + bonus
            result[ce][(d.year, d.month)] += total

    final = {}
    for eid in result:
        months = sorted(result[eid].keys())  # sorted by billing month ascending
        salaries = []
        for m in months:
            val = result[eid][m]
            salaries.append(int(round(val)))
        final[eid] = salaries

    return final


if __name__ == '__main__':
    with open('/app/answer.json', 'w') as f:
        json.dump(answer(), f, default=list)
